CREATE OR REPLACE FUNCTION calculate_credit_score(
    p_credscore SMALLINT,
    p_credutil DECIMAL(5,3),
    p_debincratio DECIMAL(5,3),
    p_credageyrs SMALLINT,
    p_delinqcount SMALLINT,
    p_latepaycount SMALLINT,
    p_choffs SMALLINT,
    p_bankr SMALLINT
) RETURNS NUMERIC AS $ $
DECLARE
    computed_score NUMERIC;
BEGIN
    -- Define the formula for calculating the Credit Score
    computed_score := p_credscore * (1 - p_credutil) * (1 - p_debincratio) * (1 + p_credageyrs) * (1 - p_delinqcount) * (1 - p_latepaycount) * (1 - p_choffs) * (1 - p_bankr);
    RETURN computed_score;
END;
$ $ LANGUAGE plpgsql;

